// Lista os pedidos do período. 'Consulta sem registros' (codigo 20) é fim
// normal de ciclo, não erro — período sem pedidos novos.
const ret = $input.first().json?.retorno ?? {};
if (ret.status !== 'OK') {
  const cod = Number(ret.codigo_erro ?? 0);
  if (cod === 20) return []; // nenhum pedido no período
  throw new Error('pedidos.pesquisa (GreenPallets) falhou: ' + JSON.stringify(ret.erros ?? ret));
}
const lista = Array.isArray(ret.pedidos) ? ret.pedidos : (ret.pedidos ? [ret.pedidos] : []);
const saida = [];
for (const x of lista) {
  const p = x.pedido || x;
  const sit = String(p.situacao ?? '').toLowerCase();
  if (sit.includes('cancel')) continue; // cancelado antes do poll não vira card
  const tiny_id = Number(p.id);
  const numero = Number(p.numero);
  if (!tiny_id || !numero) continue;
  saida.push({ json: { tiny_id, numero } });
}
return saida;

// Gera uma linha por UNIDADE a produzir — mesmo algoritmo verificado contra
// as 758 linhas da PCP, adaptado para processar VÁRIOS pedidos por ciclo
// (o polling pode trazer mais de um pedido novo de uma vez).

// Prefixo de origem: distingue os cards da GreenPallets dos da Domoby na
// mesma coluna 'pedido'. Para remover no futuro, troque por ''.
const PREFIXO = 'GP-';

const norm = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();
const lista = (v) => (Array.isArray(v) ? v : v ? [v] : []);

const saida = [];
for (const entrada of $input.all()) {
  const p = entrada.json?.retorno?.pedido ?? {};
  const pedido = norm(p.numero);
  if (!pedido) continue;

  // data de entrega: dd/mm/yyyy -> ISO, meio-dia em Fortaleza
  const prev = norm(p.data_prevista);
  let dueISO = '';
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(prev)) {
    const [d, m, y] = prev.split('/').map(Number);
    dueISO = new Date(Date.UTC(y, m - 1, d, 15, 0, 0)).toISOString();
  }

  // expande cada item pela quantidade -> uma entrada por unidade
  const unidades = [];
  for (const raw of lista(p.itens)) {
    const i = raw.item || raw;
    const qtd = Math.round(parseFloat(String(i.quantidade ?? '0').replace(',', '.')) || 0);
    if (qtd < 1) continue; // item com quantidade 0 não vira card
    const base = `${PREFIXO}${pedido} - ${norm(i.descricao)}`;
    for (let k = 0; k < qtd; k++) unidades.push(base);
  }

  // marcador (k/n) calculado DENTRO de cada pedido
  const total = {};
  for (const u of unidades) total[u] = (total[u] || 0) + 1;
  const visto = {};
  for (const u of unidades) {
    visto[u] = (visto[u] || 0) + 1;
    saida.push({ json: {
      nomeCard: `${u} (${visto[u]}/${total[u]})`,
      dueDate: dueISO,
      pedido,
    }});
  }
}
return saida;
